fun=result.replace(/(<|>)/g,' $1 ').match(/(eval\([\s\S]+?,\{\}\)\))/)[1];
eval(fun);

list=cInfo.fs;

//线路
var pageConfig = {
    'host': {
        'auto': ['images.720rs.com'],    //主线
        'telecom': ['images.tingliu.cc'],     //备用1
        'unicom': ['images02.piaoyaozhe.com'] //备用2
    }
}
html='';

for(i in list){
//更改切换线路
host='http://'+pageConfig.host.telecom[0];

html += '<img src="'+host + list[i]+'">\n'
}
html

